import os
import requests
from concurrent.futures import ThreadPoolExecutor, as_completed

PERSPECTIVE_API_KEY = os.getenv("PERSPECTIVE_API_KEY")
ENDPOINT = "https://commentanalyzer.googleapis.com/v1alpha1/comments:analyze"
ATTRIBUTES = ["TOXICITY", "SEVERE_TOXICITY", "IDENTITY_ATTACK", "INSULT", "PROFANITY", "THREAT", "SEXUALLY_EXPLICIT"]

def analyze_comment(text):
    payload = {
        "comment": {"text": text},
        "requestedAttributes": {attr: {} for attr in ATTRIBUTES}
    }
    headers = {"apiKey": PERSPECTIVE_API_KEY}
    response = requests.post(ENDPOINT, json=payload, headers=headers)
    response.raise_for_status()
    result = response.json()["attributeScores"]
    decisions = {}
    for attr in ATTRIBUTES:
        score = result[attr]["summaryScore"]["value"]
        decisions[attr] = score >= 0.5  # simple threshold decision
    return decisions

def moderate_messages(messages):
    with ThreadPoolExecutor() as executor:
        future_to_message = {executor.submit(analyze_comment, msg): msg for msg in messages}
        results = []
        for future in as_completed(future_to_message):
            message = future_to_message[future]
            try:
                decisions = future.result()
            except Exception as e:
                decisions = {"error": str(e)}
            results.append({"message": message, "decisions": decisions})
    return results

# Example usage
if __name__ == "__main__":
    sample_messages = [
        "This is a harmless message.",
        "I hate you, you are worthless!",
        "Buy our product now!",
        "You are an idiot and should not be allowed to speak."
    ]
    moderation_results = moderate_messages(sample_messages)
    for result in moderation_results:
        print(result)
